/* global test expect */
import { DateTime } from "../../src/luxon";

// proleptic gregorian day number
function toDays(y, m, d) {
  const a = Math.floor((14 - m) / 12);
  const yy = y + 4800 - a;
  const mm = m + 12 * a - 3;
  return d + Math.floor((153 * mm + 2) / 5) + 365 * yy + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400) - 32045;
}
function fromDays(jdn) {
  let a = jdn + 32044;
  let b = Math.floor((4 * a + 3) / 146097);
  let c = a - Math.floor(146097 * b / 4);
  let d = Math.floor((4 * c + 3) / 1461);
  let e = c - Math.floor(1461 * d / 4);
  let m = Math.floor((5 * e + 2) / 153);
  const day = e - Math.floor((153 * m + 2) / 5) + 1;
  const month = m + 3 - 12 * Math.floor(m / 10);
  const year = 100 * b + d - 4800 + Math.floor(m / 10);
  return [year, month, day];
}

test("brute force plus days", () => {
  const fails = [];
  for (let y = 90; y <= 110; y++) {
    for (const [m, d] of [[1,1],[1,31],[2,1],[2,27],[2,28],[3,1],[12,31],[6,15]]) {
      for (const n of [-400,-366,-60,-59,-31,-1,0,1,28,29,30,31,59,60,61,365,366,400]) {
        const start = DateTime.fromISO(`${String(y).padStart(4,"0")}-${String(m).padStart(2,"0")}-${String(d).padStart(2,"0")}`, {zone: "utc"});
        if (!start.isValid) continue;
        const got = start.plus({ days: n });
        const [ey, em, ed] = fromDays(toDays(y, m, d) + n);
        if (got.year !== ey || got.month !== em || got.day !== ed) {
          fails.push(`${y}-${m}-${d} + ${n} => got ${got.year}-${got.month}-${got.day}, want ${ey}-${em}-${ed}`);
        }
      }
    }
  }
  console.log("FAILS:", fails.length);
  console.log(fails.slice(0, 40).join("\n"));
});
